public class Main {
    public static void main(String[] args) {
        java.util.List<java.util.Map<String, Object>> rows = java.util.List.of(
            java.util.Map.of("name", "Мира", "active", true),
            java.util.Map.of("name", "Олег", "active", false));
        for (var row : rows) {
            if (Boolean.TRUE.equals(row.get("active"))) System.out.println(row.get("name"));
        }
        var names = java.util.Map.of(3, "Мира");
        var cities = java.util.Map.of(3, "Рига");
        for (int id : names.keySet()) {
            if (cities.containsKey(id)) System.out.println(names.get(id) + ":" + cities.get(id));
        }
    }
}
